import { useEffect, useRef } from "react";
import { Terminal as XTerm } from "xterm";
import { FitAddon } from "xterm-addon-fit";
import "xterm/css/xterm.css";
// @ts-ignore wailsjs bindings are generated by wails build
import { ResizePty, StreamPtyData, WritePty } from "../../../wailsjs/go/controllers/Terminal";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../../wailsjs/runtime";

// One xterm.js instance per pane. Talks to the Go PTY through the
// Terminal controller: StreamPtyData starts the output pump, WritePty
// sends keystrokes, ResizePty follows the fit addon.
export default function Terminal({
  sessionId,
  onExit,
}: {
  sessionId: string;
  onExit: () => void;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const termRef = useRef<XTerm | null>(null);
  const fitRef = useRef<FitAddon | null>(null);

  useEffect(() => {
    if (!containerRef.current || termRef.current) return;

    const term = new XTerm({
      cursorBlink: true,
      cursorStyle: "block",
      fontSize: 13,
      fontFamily: "JetBrains Mono, Menlo, monospace",
      scrollback: 5000,
      theme: {
        background: "#171717",
        foreground: "#e4e6ff",
        cursor: "#7c5cff",
        selectionBackground: "#3d3d6b",
      },
    });
    const fit = new FitAddon();
    term.loadAddon(fit);
    term.open(containerRef.current);
    termRef.current = term;
    fitRef.current = fit;

    // Fit after the font loads so cell measurement is correct.
    const fontLoad = document.fonts?.load("13px JetBrains Mono");
    const doFit = () => {
      try {
        fit.fit();
      } catch {
        /* not yet in DOM */
      }
    };
    if (fontLoad) {
      fontLoad.then(() => doFit()).catch(() => doFit());
    } else {
      doFit();
    }

    // Start the PTY output stream and wire the event.
    StreamPtyData(sessionId).catch(() => { /* session may have died */ });
    const cancelData = EventsOn("term:data", (payload: { id: string; data: string }) => {
      if (payload?.id === sessionId) {
        term.write(payload.data);
      }
    });
    const cancelExit = EventsOn("term:exit", (payload: { id: string }) => {
      if (payload?.id === sessionId) {
        term.write("\r\n\x1b[90m[process exited]\x1b[0m\r\n");
        onExit();
      }
    });

    // Keyboard input → PTY.
    term.onData((data) => {
      WritePty(sessionId, data).catch(() => { /* session died */ });
    });

    // Resize observer → PTY resize.
    const observer = new ResizeObserver(() => {
      doFit();
      if (term.cols > 0 && term.rows > 0) {
        ResizePty(sessionId, term.cols, term.rows).catch(() => { /* dead */ });
      }
    });
    observer.observe(containerRef.current);

    return () => {
      cancelData?.();
      cancelExit?.();
      observer.disconnect();
      term.dispose();
      termRef.current = null;
      fitRef.current = null;
    };
  }, [sessionId]); // eslint-disable-line react-hooks/exhaustive-deps

  return <div ref={containerRef} className="h-full w-full overflow-hidden" />;
}
